import Image from "next/image";
// import heroImg from "@/public/hero-woman.jpg"; // Place your image in public folder and name it hero-woman.png

export default function Hero() {
  return (
    <section className="bg-blue-700 min-h-screen flex items-center justify-center">
      <div className="max-w-7xl w-full grid grid-cols-1 md:grid-cols-2 items-center p-6 md:p-16 gap-10">

        {/* Left Content */}
        <div className="text-white space-y-6">
          <p className="text-sm font-light">Software Recruitment Specialists</p>
          <h1 className="text-4xl md:text-5xl font-bold leading-tight">Elevate your career</h1>

          <div className="flex max-w-md overflow-hidden rounded-full bg-white shadow-md">
            <input
              type="text"
              placeholder="E.g. networking"
              className="flex-grow px-6 py-3 rounded-l-full focus:outline-none text-gray-700"
            />
            <button className="bg-yellow-400 px-6 py-3 text-sm font-semibold text-gray-800 rounded-r-full">
              Search jobs
            </button>
          </div>
        </div>

        {/* Right Content */}
        <div className="relative flex justify-center items-center">
          <div className="bg-white rounded-[2rem] overflow-hidden w-full max-w-sm">
            <Image
              src='/images/hero-women.jpg'
              width={250}
              height={250}
              alt="Woman holding laptop"
              className="w-full h-auto object-cover"
              priority
            />
          </div>
        </div>
      </div>
    </section>
  );
}
